323	/// A potentially overshooting coordinate within an animation.
324	///
325	/// Phases are not restricted to 0..1. Multi-stage animations can assign each
326	/// stage its own coordinate and interpolate over ranges such as 1..=2.
327	#[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd)]
328	pub struct AnimationPhase(
329	    /// The unbounded phase coordinate.
330	    pub f32,
331	);
332	
333	impl AnimationPhase {
334	    /// Restricts this phase to the bounds of a range.
335	    pub fn clamp(self, range: RangeInclusive<f32>) -> Self {
336	        let (first, second) = range.into_inner();
337	        Self(self.0.clamp(first.min(second), first.max(second)))
338	    }
339	
340	    /// Interpolates between values using 0 and 1 as their phase coordinates.
341	    pub fn interpolate<T: Interpolate>(self, from: T, to: T) -> T {
342	        T::interpolate(from, to, self.0)
343	    }
344	
345	    /// Interpolates between values without extrapolating beyond 0 and 1.
346	    pub fn interpolate_clamped<T: Interpolate>(self, from: T, to: T) -> T {
347	        T::interpolate(from, to, self.0.clamp(0.0, 1.0))
348	    }
349	
350	    /// Interpolates between values assigned to arbitrary phase coordinates.
351	    pub fn interpolate_between<T: Interpolate>(
352	        self,
353	        range: RangeInclusive<f32>,
354	        from: T,
355	        to: T,
356	    ) -> T {
357	        let (start, end) = range.into_inner();
358	        let phase = if start == end {
359	            if self.0 < start { 0.0 } else { 1.0 }
360	        } else {
361	            (self.0 - start) / (end - start)
362	        };
363	        T::interpolate(from, to, phase)
364	    }
365	
366	    /// Interpolates over arbitrary phase coordinates without extrapolating.
367	    pub fn interpolate_between_clamped<T: Interpolate>(
368	        self,
369	        range: RangeInclusive<f32>,
370	        from: T,
371	        to: T,
372	    ) -> T {
373	        let (start, end) = range.into_inner();
374	        let phase = if start == end {
375	            if self.0 < start { 0.0 } else { 1.0 }
376	        } else {
377	            ((self.0 - start) / (end - start)).clamp(0.0, 1.0)
378	        };
379	        T::interpolate(from, to, phase)
380	    }
381	}
