533	/// Adapts a spring starting at zero with no velocity to GPUI's duration-based easing API.
534	///
535	/// The returned easing can overshoot the normalized 0..1 output range. Retargeting
536	/// this duration-based form restarts the spring; use [`SpringConfig::step`] when
537	/// preserving velocity matters.
538	pub fn sampled_easing(config: SpringConfig, epsilon: f32) -> (Duration, impl Fn(f32) -> f32) {
539	    let initial_state = SpringState {
540	        position: 0.0,
541	        velocity: 0.0,
542	    };
543	    let duration = config.settle_time(initial_state, 1.0, epsilon);
544	    let duration_seconds = duration.as_secs_f32();
545	
546	    (duration, move |progress| {
547	        if progress <= 0.0 {
548	            0.0
549	        } else if progress >= 1.0 {
550	            1.0
551	        } else {
552	            config
553	                .step(initial_state, 1.0, progress * duration_seconds)
554	                .position
555	        }
556	    })
557	}
